using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CorruptedScrappingAction", menuName = "Data/Battle/Battle Actions/Enemy/CorruptedScrapping Action")]
public class CorruptedScrappingAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private BattleAction battleAction;

	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private float startVfxDelay;

	[SerializeField]
	private float activateEffectVfxDelay;

	public BattleAction BattleAction => battleAction;

	public override void CastAmount(int amount, GameObject source)
	{
		GameObject minionToScrap = currentCorruptedAnimals.GetEnemyWithLowestCorruptionNotCorruptionSource();
		if (minionToScrap == null)
		{
			return;
		}
		CorruptedAnimalCorruptionStats component = minionToScrap.GetComponent<CorruptedAnimalCorruptionStats>();
		int actionAmount = (int)component.CurrentCorruption * amount;
		if (IsVFXEnabled())
		{
			minionToScrap.GetComponent<CorruptedAnimalCorruptionStats>().InstantlyDefeatEnemy();
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, startVfxDelay, delegate
			{
				PlaySFX();
				SpawnVFX(GetVFXOwnerPosition(minionToScrap), 5f);
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, activateEffectVfxDelay, delegate
				{
					omenLogic.ActivateOmen(battleAction, actionAmount, null, source);
				});
			});
		}
		else
		{
			minionToScrap.GetComponent<CorruptedAnimalCorruptionStats>().InstantlyDefeatEnemy();
			omenLogic.ActivateOmen(battleAction, actionAmount, null, source);
		}
	}
}
